import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.DMtjdCb-.js";const i="/help/assets/hidden-works.en.CsvrCD_l.png",o="/help/assets/library-settings.en.CXGqbpfv.png",n="/help/assets/history.en.C94vjIuy.png",m=JSON.parse('{"title":"8. Daily use","description":"","frontmatter":{},"headers":[],"relativePath":"en/manage.md","filePath":"en/manage.md"}'),d={name:"en/manage.md"};function l(c,e,h,p,u,g){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_8-daily-use" tabindex="-1">8. Daily use <a class="header-anchor" href="#_8-daily-use" aria-label="Permalink to &quot;8. Daily use&quot;">​</a></h1><h2 id="find-filter-and-hide-titles" tabindex="-1">Find, filter, and hide titles <a class="header-anchor" href="#find-filter-and-hide-titles" aria-label="Permalink to &quot;Find, filter, and hide titles&quot;">​</a></h2><p>Switch between cards and a table, and filter by year, type, resource source, or collection status. <strong>Reset all</strong> restores the default filters. A title search can still find titles excluded by defaults or hidden by you.</p><p>Set a title to <strong>Hidden</strong> in the radar or details to remove it from default browsing. Its subscription, downloads, and viewing records remain intact.</p><p>To restore it, open <strong>Release radar → Hidden titles</strong>, find it, and choose <strong>Show again</strong>.</p><p><img src="'+i+'" alt="Hidden titles: search and restore" loading="lazy"></p><h2 id="pause-cancel-or-delete-a-subscription" tabindex="-1">Pause, cancel, or delete a subscription <a class="header-anchor" href="#pause-cancel-or-delete-a-subscription" aria-label="Permalink to &quot;Pause, cancel, or delete a subscription&quot;">​</a></h2><p>Use the subscription status menu in the radar or title details:</p><table tabindex="0"><thead><tr><th>Action</th><th>Later episodes</th><th>Existing files</th></tr></thead><tbody><tr><td>Pause subscription</td><td>Paused; can resume</td><td>Kept</td></tr><tr><td>Cancel subscription, keep files</td><td>Subscription stops</td><td>Kept</td></tr><tr><td>Delete subscription and files</td><td>Subscription removed</td><td>Deleted as described in the confirmation</td></tr><tr><td>Hide title</td><td>Subscription continues</td><td>Kept</td></tr></tbody></table><p>For deletion, check the title and file scope in the confirmation before proceeding.</p><h2 id="create-subscription-folders" tabindex="-1">Create subscription folders <a class="header-anchor" href="#create-subscription-folders" aria-label="Permalink to &quot;Create subscription folders&quot;">​</a></h2><p>When the local library is connected and writable, <strong>Folders</strong> in the radar creates placeholder folders for subscribed titles. Existing folders are reused; check the result in History.</p><h2 id="set-library-quiet-hours" tabindex="-1">Set library quiet hours <a class="header-anchor" href="#set-library-quiet-hours" aria-label="Permalink to &quot;Set library quiet hours&quot;">​</a></h2><ol><li>Open <strong>Settings → Connections → Local library</strong>.</li><li>Enable daily quiet hours and set their start and end times.</li><li>Check the server clock shown on the page, then save.</li></ol><p><img src="'+o+'" alt="Quiet hours: check the runtime device clock" loading="lazy"></p><p>Times follow the device running AnimeMachine and can cross midnight. Local-library access pauses during the interval; cached status remains available and Ani-RSS and other media sources continue independently.</p><p>This setting controls AnimeMachine&#39;s access. Other applications may still use the disk; physical disk sleep also depends on the NAS and those services.</p><h2 id="read-history-and-logs" tabindex="-1">Read History and Logs <a class="header-anchor" href="#read-history-and-logs" aria-label="Permalink to &quot;Read History and Logs&quot;">​</a></h2><p><strong>Settings → History</strong> lists completed organization, folder, and download operations. <strong>Settings → Logs</strong> shows runtime messages. Filter to warnings and errors, then search by title or keyword.</p><p><img src="'+n+'" alt="History: find an operation and its result" loading="lazy"></p><h2 id="correct-media-matches" tabindex="-1">Correct media matches <a class="header-anchor" href="#correct-media-matches" aria-label="Permalink to &quot;Correct media matches&quot;">​</a></h2><p>If files appear under the wrong title or have incorrect episode numbers, open <strong>Settings → General → Correct media matches</strong>:</p><ol><li>Search by folder or filename. Choose <strong>All files</strong> to change an existing match.</li><li>Find and select the correct title, select the files, and check or edit their episode numbers.</li><li>Click <strong>Save matches</strong>, then check the playlist in title details.</li></ol><p>Only identification records change; files remain in place. To undo a correction, select the corrected files and click <strong>Use automatic matching</strong>.</p><h2 id="check-background-tasks" tabindex="-1">Check background tasks <a class="header-anchor" href="#check-background-tasks" aria-label="Permalink to &quot;Check background tasks&quot;">​</a></h2><p>Click <strong>Background tasks</strong> at the top of the page to check cover preparation, catalog updates, resource searches and local verification. Failed tasks show a message; supported tasks offer <strong>Retry</strong> without restarting the app.</p>',26)])])}const f=t(d,[["render",l]]);export{m as __pageData,f as default};
